function OverseaClubBossRankClubNodeCell:Refresh(data)
    self.data = data
    self.rank = data.ranking
    self:FillRankInfo()
    CfUtils.FillText(self.MasterName,self.data.chairmanName)
    CfUtils.FillText(self.ClubName,self.data.clubName)
    CfUtils.FillText(self.DamageNum,self.data.score)

    local clubHeadVo = ClubUtils.GetClubHeadVo(self.data.clubAvatar)
    if not isNull(clubHeadVo) then
        CfUtils.FillImage(self.ClubHead,clubHeadVo.photoPath)
    end
end

function OverseaClubBossRankClubNodeCell:FillRankInfo()
    local isMySelf = self:IsMyClub(self.data.clubId)
    CfUtils.SetActive(self.ImgMyself,isMySelf)
    CfUtils.SetUISwitchText(self.MySelfText,2)
    local status = self.rank
    if self.rank > 3 then
        status = 4
    end
    CfUtils.SetUISwitchImage(self.ImgRank1,status)
    CfUtils.SetUISwitchImage(self.ImgRank2,status)
    CfUtils.FillText(self.Rank,self.rank)
end

function OverseaClubBossRankClubNodeCell:PlayAnimByHide()
    CfUtils.PlayAnimation(self.AniRoot, 'UI_Common_List_Cell_Hide')
end


function OverseaClubBossRankClubNodeCell:PlayAnimByIdle()
    CfUtils.PlayAnimation(self.AniRoot, 'UI_Common_List_Cell_Idle')
end


function OverseaClubBossRankClubNodeCell:PlayDelayAnimByShow(delayIndex)
    CfUtils.PlayDelayShowAnimation(self.AniRoot, delayIndex, 'UI_Common_List_Cell_Show')
end

function OverseaClubBossRankClubNodeCell:IsMyClub(id)
    local clubHomeDojo = ClubUtils.GetClubComp():GetHomeDojo()
    local clubId = clubHomeDojo.clubId
    return checkNumber(clubId) == id
end

function OverseaClubBossRankClubNodeCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

